+pub fn hello_ok_line(token: &str, nonce: Option<&str>) -> String {
+    match nonce {
+        None => HELLO_OK.to_owned(),
+        Some(n) => json!({ "camcraft_link": FORMAT, "ok": true, "proof": token_proof(token, n) })
+            .to_string(),
+    }
+}
